        throw std::runtime_error("KimiK3DeltaAttention: num_heads must be divisible by tp_size");
    }
    if (rank_info.tp_size > 1 && !rank_info.comm) {
        throw std::invalid_argument("KimiK3DeltaAttention: TP communicator is missing");
    }
