        lm_head_ = std::make_shared<infinilm::layers::linear::ReplicatedLinear>(
            runtime, hidden_size, vocab_size, false, dtype);
        this->bind_child("lm_head", lm_head_);
    } catch (...) {
        const auto failure = std::current_exception();
