            self_attn_ = std::make_shared<Qwen3NextAttention>(
                runtime, model_config, layer_idx, rank_info, attention_backend, ep_config);
            this->bind_child("self_attn", self_attn_);
        }
    } catch (...) {
        const auto failure = std::current_exception();
        try {
